/// <summary>
/// Controller class for transfer picking list generation service
/// </summary>
class METTransferPickingListAutoGenerationController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>Constuct new object</summary>
/// <param name = "_args">Arguments</param>
/// <param name = "_executionMode">Execution mode</param>
/// <returns>New Controller Object</returns>
public static SysOperationController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    SysOperationController controller = new METTransferPickingListAutoGenerationController();
    controller.parmExecutionMode(_executionMode);
    controller.parmArgs(_args);

    return controller;
}

/// <summary>New object</summary>
protected void new()
{
    super(classstr(METTransferPickingListGenerationService), methodstr(METTransferPickingListGenerationService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>Main method</summary>
/// <param name = "_args">Arguments</param>
public static void main(Args _args)
{
    METTransferPickingListGenerationContract    dataContract;
    METTransferPickingListAutoGenerationController  controller;

    controller      = METTransferPickingListAutoGenerationController::construct(_args);
    dataContract    = controller.getDataContractObject();

    controller.parmShowDialog(true);
    controller.startOperation();
}

/// <summary>
/// Description
/// </summary>
/// <returns>Generate purchase orders</returns>
public ClassDescription defaultCaption()
{
    return "Automatically extract transfer orders";
}
